/// Means for complete windows; accumulation must not overflow for u64 inputs.
pub fn moving_average(values: &[u64], window: usize) -> Result<Vec<u64>, &'static str> {
    if window == 0 {
        return Err("window must be positive");
    }
    if window > values.len() {
        return Ok(Vec::new());
    }
    let mut sum: u128 = values[..window].iter().map(|&value| u128::from(value)).sum();
    let mut output = Vec::with_capacity(values.len() - window + 1);
    output.push((sum / window as u128) as u64);
    for index in window..values.len() {
        sum -= u128::from(values[index - window]);
        sum += u128::from(values[index]);
        output.push((sum / window as u128) as u64);
    }
    Ok(output)
}

